fn numpy_insert<T>(arr: Vec<T>, idx: usize, value: T) -> Vec<T> {
    // Create a new vector with capacity for one more element
    let mut result = Vec::with_capacity(arr.len() + 1);

    // Push all elements before idx as is
    for i in 0..idx {
        // Using `get_unchecked` is unsafe, so we use indexing safely here
        result.push(arr[i].clone());
    }

    // Insert the new value at position idx
    result.push(value);

    // Append the remaining elements shifted by one
    for i in idx..arr.len() {
        result.push(arr[i].clone());
    }

    result
}